const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error("Aucun fichier CSV reçu. Merci de joindre l'export CSV Keyword Planner.");
}
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKeys[0]);

let text;
if (buffer[0] === 0xFF && buffer[1] === 0xFE) {
  text = buffer.toString('utf16le');
} else if (buffer[0] === 0xFE && buffer[1] === 0xFF) {
  text = buffer.swap16().toString('utf16le');
} else {
  text = buffer.toString('utf8');
}
text = text.replace(/^\uFEFF/, '');

const lines = text.split(/\r?\n/).filter(l => l.length > 0);
const headerLineIndex = lines.findIndex(l => l.startsWith('Keyword\t'));
if (headerLineIndex === -1) {
  throw new Error("Format de fichier non reconnu : en-tête 'Keyword' introuvable.");
}
const dataLines = lines.slice(headerLineIndex + 1);

function parsePct(s) {
  if (!s || s === '∞') return null;
  const n = parseFloat(s.replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}

const rows = dataLines.map(line => {
  const cols = line.split('\t');
  return {
    keyword: cols[0] || '',
    avgMonthlySearches: cols[2] && cols[2].trim() !== '' ? parseInt(cols[2], 10) : null,
    var3mPct: parsePct(cols[3]),
    varYoyPct: parsePct(cols[4]),
    competition: cols[5] && cols[5].trim() !== '' ? cols[5] : 'Inconnu',
    competitionIndexed: cols[6] && /^[0-9]+$/.test(cols[6].trim()) ? parseInt(cols[6], 10) : null
  };
});

const form = item.json;
const contains = (form['Mot-clé contient'] || '').toString().toLowerCase().trim();
const minVol = form['Volume mensuel minimum'] !== undefined && form['Volume mensuel minimum'] !== '' && form['Volume mensuel minimum'] !== null ? Number(form['Volume mensuel minimum']) : null;
const maxVol = form['Volume mensuel maximum'] !== undefined && form['Volume mensuel maximum'] !== '' && form['Volume mensuel maximum'] !== null ? Number(form['Volume mensuel maximum']) : null;
const competitionFilter = form['Niveau de concurrence'] || 'Tous';
const minYoy = form['Variation YoY minimum (%)'] !== undefined && form['Variation YoY minimum (%)'] !== '' && form['Variation YoY minimum (%)'] !== null ? Number(form['Variation YoY minimum (%)']) : null;

let filtered = rows.filter(r => {
  if (contains && !r.keyword.toLowerCase().includes(contains)) return false;
  if (minVol !== null && (r.avgMonthlySearches === null || r.avgMonthlySearches < minVol)) return false;
  if (maxVol !== null && (r.avgMonthlySearches === null || r.avgMonthlySearches > maxVol)) return false;
  if (competitionFilter && competitionFilter !== 'Tous' && r.competition !== competitionFilter) return false;
  if (minYoy !== null && (r.varYoyPct === null || r.varYoyPct < minYoy)) return false;
  return true;
});

filtered.sort((a, b) => (b.avgMonthlySearches || 0) - (a.avgMonthlySearches || 0));

const maxDisplay = 500;
const truncated = filtered.length > maxDisplay;
const displayRows = filtered.slice(0, maxDisplay);

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const tableRows = displayRows.map(function(r) {
  return '<tr><td>' + escapeHtml(r.keyword) + '</td><td>' + (r.avgMonthlySearches !== null ? r.avgMonthlySearches : '') + '</td><td>' + escapeHtml(r.competition) + '</td><td>' + (r.varYoyPct !== null ? r.varYoyPct + '%' : '') + '</td></tr>';
}).join('');

const html = '<div style="text-align:left;max-height:480px;overflow:auto;">'
  + '<p><strong>' + filtered.length + '</strong> mot(s)-clé(s) trouvé(s)' + (truncated ? ' (affichage limité aux 500 premiers, triés par volume décroissant)' : '') + '.</p>'
  + '<table border="1" cellpadding="4" style="border-collapse:collapse;width:100%;font-size:13px;">'
  + '<tr><th>Mot-clé</th><th>Volume mensuel moyen</th><th>Concurrence</th><th>Variation YoY</th></tr>'
  + tableRows
  + '</table></div>';

return [{ json: { resultHtml: html, count: filtered.length, keywords: filtered.map(r => r.keyword) } }];
